-- Panel privado para administrar las aplicaciones y revisar propuestas de contenido.
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.managed_apps (id text primary key check (id ~ '^[a-z0-9-]+$'), name text not null, description text not null default '', icon text not null default '✨', status text not null default 'configuration' check (status in ('active','configuration','paused')), public_url text, repository_url text, supabase_project_ref text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.content_proposals (id uuid primary key default gen_random_uuid(), app_id text not null references public.managed_apps(id) on delete cascade, title text not null, kind text not null default 'content', summary text not null, preview jsonb not null default '{}'::jsonb, source_url text, status text not null default 'pending' check (status in ('pending','approved','changes_requested','rejected','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.proposal_reviews (id uuid primary key default gen_random_uuid(), proposal_id uuid not null references public.content_proposals(id) on delete cascade, reviewer_id uuid not null references auth.users(id) on delete cascade, decision text not null check (decision in ('approved','changes_requested','rejected')), comment text not null default '', created_at timestamptz not null default now());
create table if not exists public.agent_runs (id uuid primary key default gen_random_uuid(), app_id text not null references public.managed_apps(id) on delete cascade, agent_name text not null, status text not null check (status in ('ready','running','success','failed','disabled')), summary text not null default '', source_url text, started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now());
alter table public.admin_users enable row level security; alter table public.managed_apps enable row level security; alter table public.content_proposals enable row level security; alter table public.proposal_reviews enable row level security; alter table public.agent_runs enable row level security;
create policy "admin can read own membership" on public.admin_users for select to authenticated using (user_id = (select auth.uid()));
create policy "admins manage apps" on public.managed_apps for all to authenticated using (exists (select 1 from public.admin_users where user_id=(select auth.uid()))) with check (exists (select 1 from public.admin_users where user_id=(select auth.uid())));
create policy "admins manage proposals" on public.content_proposals for all to authenticated using (exists (select 1 from public.admin_users where user_id=(select auth.uid()))) with check (exists (select 1 from public.admin_users where user_id=(select auth.uid())));
create policy "admins manage reviews" on public.proposal_reviews for all to authenticated using (exists (select 1 from public.admin_users where user_id=(select auth.uid()))) with check (exists (select 1 from public.admin_users where user_id=(select auth.uid())) and reviewer_id=(select auth.uid()));
create policy "admins manage agent runs" on public.agent_runs for all to authenticated using (exists (select 1 from public.admin_users where user_id=(select auth.uid()))) with check (exists (select 1 from public.admin_users where user_id=(select auth.uid())));
revoke all on table public.admin_users, public.managed_apps, public.content_proposals, public.proposal_reviews, public.agent_runs from anon;
grant select on table public.admin_users to authenticated; grant select, insert, update, delete on table public.managed_apps, public.content_proposals, public.proposal_reviews, public.agent_runs to authenticated;
create or replace function public.review_content_proposal(proposal uuid,new_decision text,review_comment text default '') returns public.content_proposals language plpgsql security invoker set search_path = '' as $$ declare reviewed public.content_proposals; begin if new_decision not in ('approved','changes_requested','rejected') then raise exception 'Decisión no válida'; end if; update public.content_proposals set status=new_decision,updated_at=now() where id=proposal and status in ('pending','changes_requested') returning * into reviewed; if reviewed.id is null then raise exception 'La propuesta ya fue revisada o no existe'; end if; insert into public.proposal_reviews(proposal_id,reviewer_id,decision,comment) values(proposal,(select auth.uid()),new_decision,coalesce(review_comment,'')); return reviewed; end; $$;
revoke all on function public.review_content_proposal(uuid,text,text) from public; grant execute on function public.review_content_proposal(uuid,text,text) to authenticated;
insert into public.managed_apps(id,name,description,icon,status,public_url,repository_url,supabase_project_ref) values ('tinkie','Tinkie','Lectura, misiones, cuentos y acompañamiento familiar.','🦜','active','https://aprendeconmigo.angsys.com','https://github.com/Tsukima/Juegos-didacticos','yicqgbycigyhniaozrez'),('cafetin','El Cafetín','Sitio y herramientas digitales del Cafetín.','☕','configuration',null,null,'syyubwjhogwhhioxscso') on conflict(id) do update set name=excluded.name,description=excluded.description,icon=excluded.icon,supabase_project_ref=excluded.supabase_project_ref,updated_at=now();
create index if not exists content_proposals_app_id_idx on public.content_proposals(app_id);
create index if not exists proposal_reviews_proposal_id_idx on public.proposal_reviews(proposal_id);
create index if not exists proposal_reviews_reviewer_id_idx on public.proposal_reviews(reviewer_id);
create index if not exists agent_runs_app_id_idx on public.agent_runs(app_id);
